	/**  Default `paper`. */
	lightVariant: LightVariant,
	/**  Default `night`. */
	darkVariant: DarkVariant,
	/**  Default `teal`. */
	accent: Accent,
	/**  Default `en`; first run guesses from the OS locale (D22). */
