	/**  Default `auto`. */
	digits: DigitStyle,
	/**  100 (80..=200, step 10): webview zoom applied from Rust (D27). */
	uiScalePct: number,
	/**  Default `system`. */
	motion: MotionPref,
	/**  88 (65..=100; night/black only). */
	inkBrightnessPct: number,
	/**  Default `auto`. */
	chromeEffect: ChromeEffect,
	/**  Default `hafs` (onboarding offers `qcf_v2`). */
	mushafStyle: MushafStyle,
	/**  Default `auto`. */
	pageMode: PageMode,
	/**  100 (50..=300, step 10; 100 = fit to height). */
	zoomPct: number,
	/**  Default true (qcf_v4: palettes 0–2 vs 3–5). */
	tajweedColors: boolean,
	showPageFrame: boolean,
	showRunningHeads: boolean,
	showMarginMarkers: boolean,
	/**  Show bookmark, note and reading-bookmark marks in the margin (§8.9). */
	highlightBookmarks: boolean,
	hoverHighlight: boolean,
	/**  Default true (D26; false = click only selects). */
	ayahActionBar: boolean,
	pageTurnAnimation: boolean,
	wbwPackId: string | null,
	wbwTooltip: boolean,
	wbwShowTransliteration: boolean,
	/**  Default `mushaf`. */
	readingMode: ReadingMode,
	/**  Ordered pack ids, at most 5. */
	translations: string[],
	tafsirPackId: string | null,
	/**  100 (80..=200). */
	translationFontPct: number,
	translationArabic: boolean,
	footnotesInline: boolean,
	sidePane: SidePaneSettings,
	sidebar: SidebarSettings,
	/**  Default 7 (Mishary Alafasy). */
	reciterId: number,
	/**  100 (50..=200, step 5). */
	speedPct: number,
	/**  100 (0..=100). */
	volumePct: number,
	followAlong: boolean,
	wordHighlight: boolean,
	/**  1 (0..=99, 0 = ∞). */
