	/**  1 (0..=99, 0 = ∞). */
	rangeRepeat: number,
	/**  Default `none`. */
	gap: GapSetting,
	/**  Default `end_of_surah`. */
	stopAt: StopAt,
	/**  2048 (256..=20480). */
